import{t as e}from"./utils-COoNfFoj.js";var t={slug:`matic-pogladic`,influencerName:`Matic Pogladic`,influencerHandle:`@maticpogladic`,influencerAvatarUrl:`${e}/matic-pogladic-avatar.jpeg`,heroDescription:`As an entrepreneur, it’s all about building connections, finding leads, and acquiring new clients. It used to be painfully manual, but now I’ve built a tool that handles it for me—so I can focus on building my product and strengthening relationships, while leaving lead generation in the capable hands of Perplexity Computer.`,assetTitle:`SignalForge LinkedIn Lead Ops`,screenshotUrl:`${e}/matic-pogladic.png`,remixUrl:`https://www.perplexity.ai/computer/a/signalforge-linkedin-lead-trac-ZCtoPYjORzCPPv692dfwrg`,promptTitle:`Try Matic's prompt`,promptText:`Build a LinkedIn Lead Tracker and B2B lead generation web app designed for sales and growth teams, where users can define their ICP criteria and automatically discover new matched LinkedIn profiles daily, enriched with lead scoring based on seniority, company size, and recent activity signals. Include trigger-based outreach alerts that notify users when prospects get promoted, change roles, or post about relevant pain points, along with a personalized AI message generator that creates first-touch and follow-up sequences tailored to each lead’s profile and context. Implement a unified pipeline tracker to manage conversations, track outcomes, and schedule follow-ups in a single dashboard view, and generate a weekly performance report summarizing new leads added, pipeline movement, and conversion rates. Ensure the UI is clean, minimal, and modern, with a light grey background and sharp orange highlights for key actions, metrics, and notifications.`};export{t as default};
